<main class="container"><div class="tool-layout"><section class="tool-main"><h1>PNG to PDF</h1><p>Convert one or more PNG images into a PDF directly in your browser.</p><input id="files" type="file" accept="image/png" multiple hidden><div class="upload" id="upload"><strong>🖼️ Drop PNG images here</strong><br>or click to choose files</div><button class="btn" id="make" disabled>Convert to PDF</button><div class="result" id="result">No images selected.</div></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','qr-generator.php'=>'🔐 QR Code Generator','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/smart-toolz/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/smart-toolz/tool.php">View All Tools →</a></aside></div></main>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script><script>const input=document.getElementById('files'),upload=document.getElementById('upload'),make=document.getElementById('make'),result=document.getElementById('result');upload.onclick=()=>input.click();input.onchange=()=>{const f=[...input.files];make.disabled=!f.length;result.textContent=f.length?f.length+' PNG image(s) selected.':'No images selected.'};make.onclick=async()=>{const files=[...input.files];if(!files.length)return;make.disabled=true;result.textContent='Creating PDF…';try{const{jsPDF}=window.jspdf,pdf=new jsPDF();for(let i=0;i<files.length;i++){const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(files[i])});const img=await new Promise((res,rej)=>{const x=new Image();x.onload=()=>res(x);x.onerror=rej;x.src=data});const pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),scale=Math.min((pw-20)/img.width,(ph-20)/img.height),w=img.width*scale,h=img.height*scale;if(i)pdf.addPage();pdf.addImage(data,'PNG',(pw-w)/2,(ph-h)/2,w,h)}pdf.save('png-images.pdf');result.textContent=files.length+' image(s) converted. PDF downloaded.'}catch(e){console.error(e);result.textContent='Could not create the PDF.'}finally{make.disabled=false}}</script>
